def egg_boxes(n_boxes, per, loose, full_eggs=True):
    o = S(100, 180, 92)
    bw = 180 / max(n_boxes, 1)
    for b in range(n_boxes):
        x0 = 10 + b * bw
        o += R(x0 + 2, 50, bw - 4, 40, '#D8C3A5', rx=4, sw=4)
        cols = per // 2 if per > 3 else per
        for j in range(per):
            cx = x0 + (j % cols + .5) * (bw - 4) / cols + 2
            cy = 62 + (j // cols) * 18
            o += E(round(cx, 1), cy, 5, 7, CREAM, 2.5)
    for j in range(loose):
        o += E(30 + j * 28, 140, 9, 12, CREAM, 3)
    return o
